/* Conditions extracted verbatim from https://datracker.strathfield.nsw.gov.au/document/download?key=tkz3dLoM/FQ=&fileName=DA2026.37 - 32 Boden Avenue STRATHFIELD - Notice of Determination (2.7.2026).PDF (conditions-extractor-2026-08-16) — export-conditions-2026-08-16. Do not hand-edit. */
registerRefData('nsw-cond-n-1815',{"id":1815,"pan":null,"ref":"10.2026.37.1","address":"32 Boden Ave, Strathfield 2135 NSW","description":"Demolition of existing structures and construction of a two storey dwelling with basement, swimming pool and front fence.","outcome":"approved","outcome_raw":"Approved - Delegation","outcome_source":"tracker","determined":"2026-07-02","notice_url":"https://datracker.strathfield.nsw.gov.au/document/download?key=tkz3dLoM/FQ=&fileName=DA2026.37 - 32 Boden Avenue STRATHFIELD - Notice of Determination (2.7.2026).PDF","sha256":"8728084d6e3a40f5adae769ef080e6dc7ac091cf331f88e6ffe88ae4812a21f9","pages":28,"layout":"numbered","n":77,"fetched_at":"2026-08-17T01:20:28+00:00","file":"n/1815.js","source_page":"https://datracker.strathfield.nsw.gov.au/Application/ApplicationDetails/010.2026.00000037.001","lga":"STRATHFIELD","conditions":[{"label":"1","code":null,"number":"1","title":"Compliance with Building Code of Australia and insurance requirements","text":"under Home Building Act 1989\n1. It is a condition of a development consent for development that involves\nbuilding work that the work must be carried out in accordance with the\nrequirements of the Building Code of Australia.\n2. It is a condition of a development consent for development that involves\nresidential building work for which a contract of insurance is required under\nthe Home Building Act 1989, Part 6 that a contract of insurance is in force\nbefore building work authorised to be carried out by the consent\ncommences.\n3. It is a condition of a development consent for a temporary structure used as\nan entertainment venue that the temporary structure must comply with\nPart B1 and NSW Part H102 in Volume 1 of the Building Code of Australia.\n4. In subsection (1), a reference to the Building Code of Australia is a reference\nto the Building Code of Australia as in force on the day on which the\napplication for the construction certificate was made.\n5. In subsection (3), a reference to the Building Code of Australia is a reference\nto the Building Code of Australia as in force on the day on which the\napplication for development consent was made.\n6. This section does not apply-\na. to the extent to which an exemption from a provision of the Building\nCode of Australia or a fire safety standard is in force under\nthe Environmental Planning and Assessment (Development\nCertification and Fire Safety) Regulation 2021, or\nb. to the erection of a temporary building, other than a temporary\nstructure to which subsection (3) applies.","stage":"general","stage_basis":"heading","page":3},{"label":"2","code":null,"number":"2","title":"Erection of signs","text":"1. This section applies to a development consent for development involving\nbuilding work, subdivision work or demolition work.\n2. It is a condition of the development consent that a sign must be erected in a\nprominent position on a site on which building work, subdivision work or\ndemolition work is being carried out-\na. showing the name, address and telephone number of the principal\ncertifier for the work, and\nb. showing the name of the principal contractor, if any, for the building\nwork and a telephone number on which the principal contractor\nmay be contacted outside working hours, and\nc. stating that unauthorised entry to the work site is prohibited.\n3. The sign must be-\na. maintained while the building work, subdivision work or demolition\nwork is being carried out, and\nb. removed when the work has been completed.\n4. This section does not apply in relation to-\na. building work, subdivision work or demolition work carried out\ninside an existing building, if the work does not affect the external\nwalls of the building, or\nb. Crown building work certified to comply with the Building Code of\nAustralia under the Act, Part 6.","stage":"general","stage_basis":"heading","page":3},{"label":"3","code":null,"number":"3","title":"Fulfilment of BASIX commitments","text":"It is a condition of a development consent for the following that each\ncommitment listed in a relevant BASIX certificate is fulfilled-\n1. BASIX development,\nBASIX optional development, if the development application was accompanied\nby a BASIX certificate.","stage":"general","stage_basis":"heading","page":4},{"label":"4","code":null,"number":"4","title":"Notification of Home Building Act 1989 requirements","text":"1. This section applies to a development consent for development involving\nresidential building work if the principal certifier is not the council.\n2. It is a condition of the development consent that residential building work\nmust not be carried out unless the principal certifier for the development to\nwhich the work relates has given the council written notice of the\nfollowing-\na. for work that requires a principal contractor to be appointed-\ni. the name and licence number of the principal contractor,\nand\nii. the name of the insurer of the work under the Home\nBuilding Act 1989, Part 6,\nb. for work to be carried out by an owner-builder-\ni. the name of the owner-builder, and\nii. if the owner-builder is required to hold an owner-builder\npermit under the Home Building Act 1989-the number of\nthe owner-builder permit.\n3. If the information notified under subsection (2) is no longer correct, it is a\ncondition of the development consent that further work must not be carried\nout unless the principal certifier has given the council written notice of the\nupdated information.\n4. This section does not apply in relation to Crown building work certified to\ncomply with the Building Code of Australia under the Act, Part 6.","stage":"general","stage_basis":"heading","page":4},{"label":"5","code":null,"number":"5","title":"Shoring and adequacy of adjoining property","text":"1. This section applies to a development consent for development that\ninvolves excavation that extends below the level of the base of the footings\nof a building, structure or work on adjoining land, including a structure or\nwork in a road or rail corridor.\n2. It is a condition of the development consent that the person having the\nbenefit of the development consent must, at the person’s own expense-\na. protect and support the building, structure or work on adjoining\nland from possible damage from the excavation, and\nb. if necessary, underpin the building, structure or work on adjoining\nland to prevent damage from the excavation.\n3. This section does not apply if-\na. the person having the benefit of the development consent owns the\nadjoining land, or\nb. the owner of the adjoining land gives written consent to the\ncondition not applying.","stage":"general","stage_basis":"heading","page":5},{"label":"6","code":null,"number":"6","title":"","text":"Approved plans and supporting documentation.\nDevelopment must be carried out in accordance with the following approved\nplans and documents, except where the conditions of this consent expressly\nrequire otherwise.\nApproved Plans\nDescription Reference No. Date Revision Prepared By\nARCHITECTURAL PLANS\nCover Page 00.00 11.06.26 H AFORM Architecture\nDemolition Plan 00.06 10.03.26 E AFORM Architecture\nSite Plan 00.09 17.04.26 G AFORM Architecture\nGround Floor 01.01 11.06.26 H AFORM Architecture\nFirst Floor 01.02 17.04.26 G AFORM Architecture\nBasement Plan 01.03 11.06.26 H AFORM Architecture\nRoof Plan 01.04 17.04.26 G AFORM Architecture\nElevations I 02.01 17.04.26 G AFORM Architecture\nElevations II 02.02 11.06.26 H AFORM Architecture\nSections & Fence\nElevation\n03.01 11.06.26 H AFORM Architecture\nWindow Schedule\nSheets I, II, III & IV\n04.01, 04.02,\n04.03 & 04.04\n11.06.26 H AFORM Architecture\nFinish Schedule 06.02 10.03.26 E AFORM Architecture\nLANDSCAPE PLANS\nCover Sheet 26020100-LA-000 01.04.26 P3 SLandVision\nLandscape GA Plan 26020100-LA-101 01.04.26 P3 SLandVision\nDesign Levels 26020100-LA-201 01.04.26 P3 SLandVision\nPlanting Plan 26020100-LA-103 17.04.26 P4 SLandVision\nPlanting Palette 26020100-LA-104 17.04.26 P4 SLandVision\nSTORMWATER PLANS\nCoversheet DA-SW100 12.06.26 4 JCO Consultants P/L\nGeneral Notes DA-SW101 12.06.26 4 JCO Consultants P/L\nBasement DA-SW200 12.06.26 4 JCO Consultants P/L\nGround Floor DA-SW201 12.06.26 4 JCO Consultants P/L\nRoof DA-SW202 12.06.26 4 JCO Consultants P/L\nDetails - Sheet1 DA-SW300 12.06.26 4 JCO Consultants P/L\nDetails - Sheet 2 DA-SW301 12.06.26 4 JCO Consultants P/L\nCatchment Plan DA-SW400 12.06.26 4 JCO Consultants P/L\nErosion &\nSediment Control\nDA-SW600 12.06.26 4 JCO Consultants P/L\nApproved Documentation\nDescription Reference No. Date Revision Prepared By\nArboricultural\nImpact\nAssessment\nReport\n02.03.26 Malcom Bruce\nFlood Statement 24.03.26 A JCO Consultants P/L\nWaste\nManagement Plan\n26.03.26 Ruyi Zhao\nIn the event of any inconsistency between the approved plans and documents,\nthe approved plans prevail.\nIn the event of any inconsistency with the approved plans and a condition of this\nconsent, the condition prevails.","stage":"general","stage_basis":"heading","page":5},{"label":"7","code":null,"number":"7","title":"Infrastructure Development Contributions","text":"Council has identified that the development will be subject to the imposition of\nDevelopment Contributions. In accordance with Council’s relevant Contributions\nPlan, the following monetary contributions are required.\nDEVELOPMENT CONTRIBUTIONS\nStrathfield Section 94A Indirect\nDevelopment Contributions Plan 2010\n$ 27,182.32\nTOTAL CONTRIBUTIONS $ 27,182.32\nIndexation\nThe above contributions will be indexed at the time of payment to reflect\ninflation, in accordance with the indices provided by the relevant Development\nContributions Plan. Indexation will be based on the CPI of 102.41 used to\ncalculate the above contribution amount.\nPlease email council council@strathfield.nsw.gov.au prior to the payment of\ns7.11 or s7.12 Contributions to confirm the indexed contribution payable and the\nform of payment that will be accepted by Council.\nTiming of Payment\nThe contribution must be paid and receipted by Council prior to the issue of the\nConstruction Certificate. A copy of the current Development Contributions Plans\nmay be viewed on Council’s website www.strathfield.nsw.gov.au.","stage":"general","stage_basis":"heading","page":6},{"label":"8","code":null,"number":"8","title":"Building Height","text":"The height of the building measured from Australian Height Datum (AHD) must\nnot exceed Relative Level (RL) 26.90m AHD to the parapet of the building.","stage":"general","stage_basis":"heading","page":7},{"label":"9","code":null,"number":"9","title":"Section 138 Roads Act 1993 & Section 68 Local Government Act 1993","text":"Unless otherwise specified by a condition of this consent, this Development\nConsent does not give any approval to undertake works on public infrastructure.\nSeparate approval is required under Section 138 of the Roads Act 1993 and Section\n68 of the Local Government Act 1993 for any of the following activities carried out\nin, on or over a public road (including the footpath) listed below.\nAn application is required to be lodged and approved prior to the commencement\nof any of the following works or activities.\n(a) If any excavation is to be supported by the use of below ground (cable) anchors\nthat are constructed under Council’s roadways/footways.\n(b) Swinging or hoisting goods over any part of a public road by means of a lift,\ncrane or the like;\n(c) Establishing a “works zone”;\n(d) Placing or storing materials or equipment;\n(e) Placing or storing waste containers or skip bins;\n(f) Stormwater & ancillary to public infrastructure on private land\n(g) Erecting a structure or carrying out work\nSeparate activity approvals for (a) -(g) must be obtained and evidence of the\napproval provided to the Certifying Authority prior to the issue of the Construction\nCertificate.\n(h) Pumping water from the site into the public road;\n(i) Constructing a vehicular crossing or footpath;\n(j) Digging up or disturbing the surface of a public road (e.g. Opening the road for\nthe purpose of connections to utility providers);\n(k) Stormwater & ancillary works in the road reserve; and\n(l) Pumping concrete from a public road;\nSeparate activity approvals for (h) -(l) must be obtained and evidence of the\napproval provided to the Certifying Authority prior to the activities commencing.\nThe relevant Application Forms for these activities can be downloaded from\nCouncil’s website\nwww.strathfield.nsw.gov.au\nFor further information, please contact Council’s Customer Service Centre on (02)\n9748 9999.","stage":"general","stage_basis":"heading","page":7},{"label":"10","code":null,"number":"10","title":"Vehicular Crossing - Minor Development","text":"Constructing a vehicular crossing and footpath requires a separate approval under\nSection 138 of the Roads Act 1993 prior to the commencement of those works.\nThis approval must be obtained from Council by completing and submitting a\nworks permit application.\nThe approval for a new or modified vehicular crossing will contain the plans and\nspecifications required to construct the crossing and footpath. These works must\nbe completed prior to the issue of an Occupation Certificate.","stage":"general","stage_basis":"heading","page":8},{"label":"11","code":null,"number":"11","title":"Road Opening Permit","text":"A Road Opening Permit must be obtained from Council, in the case of local or\nregional roads, or from TFNSW in the case of State roads, for every opening of a\npublic reserve to access services including sewer, stormwater drains, water mains,\ngas mains, and telecommunications before the commencement of works in the\nroad.","stage":"general","stage_basis":"heading","page":8},{"label":"12","code":null,"number":"12","title":"Demolition Inspection Fees","text":"The owner/applicant is to arrange for Council to carry out pre-commencement and\npost demolition inspections of the site.\ni. The pre -commencement inspection must be carried out by a Council\nOfficer once all site works required as part of this consent have been\ninstalled and prior to any demolition works commencing.\nii. A final, post demolition inspection must be carried out by a Council Officer\nonce all demolition works have been completed to ensure that the site is\nleft in a satisfactory manner and in accordance with the conditions of\nconsent.\niii. A total of $700 for the two (2) inspections is to be paid to Council prior to\nthe issue of the construction certificate or any demolition works\ncommencing on site.\nFees are to be paid to Council prior to issue of construction certificate or\ndemolition works commencing.\nFor booking of Inspections - The applicant/owner is to contact Council’s Customer\nService Centre (ph9748 -9999) minimum two (2) days prior to the required\ninspection.\nBUILDING WORK","stage":"general","stage_basis":"heading","page":8},{"label":"13","code":null,"number":"13","title":"Long Service Levy","text":"Before the issue of the relevant construction certificate the long service levy of\n$6,795.58, as calculated at the date of this consent, must be paid to the Long\nService Corporation of Council under the Building and Construction industry Long\nService Payments Act 1986 , section 34, and evidence of the payment is to be\nprovided to the certifier.","stage":"before_cc","stage_basis":"heading","page":9},{"label":"14","code":null,"number":"14","title":"Payment of security deposits","text":"Before the issue of the relevant construction certificate, the applicant must:\na) make payment of $21,855.00 for a security deposit and $161.50 for\nAdministration Fee to the consent authority, and\nb) if a principal certifier is required to be appointed for the development -\nprovide the principal certifier with written evidence of the payment and the\namount paid.","stage":"before_cc","stage_basis":"heading","page":9},{"label":"15","code":null,"number":"15","title":"Basix Commitments","text":"The approved BASIX Certificate must be submitted to the Principal Certifier with\nthe application for a Construction Certificate.\nAll measures and commitments as detailed in the BASIX Certificate No. 1838438S\nmust be implemented on the plans lodged with the application for the\nConstruction Certificate.","stage":"before_cc","stage_basis":"heading","page":9},{"label":"16","code":null,"number":"16","title":"Low Reflectivity Roof","text":"Roofing materials must be low glare and reflectivity. Details of finished external\nmaterials must be provided to the Principal Certifier.","stage":"before_cc","stage_basis":"heading","page":9},{"label":"17","code":null,"number":"17","title":"Stormwater System","text":"The submitted stormwater plan has been assessed as a concept plan only. Final\ndetailed plans of the drainage system in accordance with Council’s Stormwater\nManagement Code and AS/NZS 3500.3: 2015 (as amended), prepared by a\nsuitably qualified professional engineer specialising in hydraulic engineering, must\nbe submitted for approval to the Principal Certifier with the Construction\nCertificate.","stage":"before_cc","stage_basis":"heading","page":9},{"label":"18","code":null,"number":"18","title":"Compliance with Flood Study","text":"The development must be designed to conform to the recommendations and\nconclusions of the submitted flood statement report prepared by JCO\nConsultants P/L Rev B dated 30/4/2026.\nThis must include, but not be limited to, any recommendations for the following:\n(a) Minimum floor levels\n(b) Fencing\n(c) Site regrading\n(d) Overland flow path construction\n(e) Protection of the basement from inundation of surface waters\nEvidence from a suitably qualified professional engineer that specialises in\nhydraulic engineering that all design requirements have been adhered to must\nbe submitted to the Principal Certifier with the Construction Certificate\napplication.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"19","code":null,"number":"19","title":"Erosion and sediment control plan","text":"Before the issue of a construction certificate, an erosion and sediment control\nplan must be prepared by a suitably qualified person in accordance with the\nfollowing documents and provided to the Certifier:\na) Council’s relevant development control plan,\nb) the guidelines set out in the NSW Department of Housing manual ‘Managing\nUrban Stormwater: Soils and Construction Certificate’ (the Blue Book) (as\namended from time to time), and\nc) the ‘Guidelines for Erosion and Sediment Control on Building Sites’\n(Department of Planning, Housing and Infrastructure)\n(dated 2024, as amended from time to time)","stage":"before_cc","stage_basis":"heading","page":10},{"label":"20","code":null,"number":"20","title":"Dial Before Your Dig","text":"The applicant must contact Home | Before You Dig Australia (BYDA) to obtain a\nService Diagram prior to the issuing of the Construction Certificate. The sequence\nnumber obtained from “Dial Before You Dig” must be forwarded to Council’s\nEngineers for their records.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"21","code":null,"number":"21","title":"Structural Details","text":"Engineer’s details for all reinforced concrete work, structural beams, columns &\nother structural members must be prepared by a suitably qualified practising\nStructural Engineer. These details are to be submitted to the Principal Certifier\nfor approval.\nA copy must be forwarded to Council where Council is not the Principal Certifier.","stage":"before_cc","stage_basis":"heading","page":10},{"label":"22","code":null,"number":"22","title":"Off Street Parking - Compliance with AS2890","text":"All driveways, access ramps, vehicular crossings and car parking spaces must be\ndesigned and constructed in accordance with the current version of Australian\nStandards, AS 2890.1 (for car parking facilities), AS 2890.6 (parking for people with\ndisabilities) and AS 2890.2 (for commercial vehicle facilities).","stage":"before_cc","stage_basis":"heading","page":11},{"label":"23","code":null,"number":"23","title":"Construction Site Management Plan","text":"Before the issue of a construction certificate, a construction site management\nplan must be prepared, and provided to the Certifier. The plan must include the\nfollowing matters:\nThe location and materials for protective fencing and hoardings on the\nperimeter of the site;\na) Provisions for public safety;\nb) Pedestrian and vehicular site access points and construction activity zones;\nc) Details of construction traffic management including:\ni) Proposed truck movements to and from the site;\nii) Estimated frequency of truck movements; and\niii) Measures to ensure pedestrian safety near the site;\nd) Details of bulk earthworks to be carried out;\ne) The location of site storage areas and sheds;\nf) The equipment used to carry out works;\ng) The location of a garbage container with a tight-fitting lid;\nh) Dust, noise and vibration control measures;\ni) The location of temporary toilets;\nj) The protective measures for the preservation of trees on-site and in\nadjoining public areas including measures in accordance with:\ni) AS 4970 - Protection of trees on development sites;\nii) An applicable Development Control Plan;\niii) An arborist’s report approved as part of this consent\nA copy of the construction site management plan must be kept on-site at all times\nwhile work is being carried out","stage":"before_cc","stage_basis":"heading","page":11},{"label":"24","code":null,"number":"24","title":"Waste Management Plan - an approved document of this consent","text":"Before the issue of a construction certificate a waste management plan for the\ndevelopment must be provided to the Certifier.","stage":"before_cc","stage_basis":"heading","page":11},{"label":"25","code":null,"number":"25","title":"Tree Bond","text":"A tree bond (calculated in accordance with Council’s adopted Fees and Charges)\nmust be paid to Council, prior to the issue of a Construction Certificate.\nTree\nnumber\nSpecies Name Height Bond Fee\nT1 Lophostemon Confertus 7.0 metres - as per\nSurvey\n$12,325.00\nA tree bond administration fee of $161.50 applies.\nThe deposit is required as security against any damage to existing trees to be\nretained on Council’s Road reserve, during works on the site. The applicant must\nbear the cost of all restoration works to Council’s property damaged during the\ncourse of this development.\nA Tree Protection fence consisting of a fully supported chainmesh fence 1.8\nmetres height x 2 metres clear of the base of the tree at any one point must be\nerected around the nominated street tree, unless otherwise specified in AS4970-\n2025.\nThe Tree Protection fence is to extend up to the back of the kerb and to the edge\nof the footpath,\nTree Protection fence is to be in place prior to commencement of demolition/\nconstruction works.\nPayment may be accepted in the form of a bank cheque, credit card or bank\nguarantee. An administration fee applies to all bonds in accordance with Council’s\nadopted Fees and Charges.\nA request for refund of the Tree Bond must be made in writing.\nTree Bonds may be forfeited if a tree is dead, made dangerous or has been\nterminally damaged, or will be held until tree/s have fully recovered from the\nconstruction damage or were replacement/planted trees have become fully\nestablished and are over 6 metres in height.","stage":"before_cc","stage_basis":"heading","page":12},{"label":"26","code":null,"number":"26","title":"Landscape Plans","text":"Stormwater Connection to Kerb is not to enter Tree 1 NRZ 2.6 metres and is to be\nhand dug using Tree sensitive methods and under the supervisor of the Project\nArborist. No roots are to be cut without the permission of Council’s Urban Forest\nsupervisor.”","stage":"before_cc","stage_basis":"heading","page":12},{"label":"27","code":null,"number":"27","title":"Tree Protection and Retention","text":"The following trees are to be protected throughout the course of all demolition and\nconstruction works. Tree protection is to be in place prior to commencement of\ndemolition works.\nTree No. Tree Species Location of Tree TPZ\nT1 Cedar deodara Southern Neighbour’s\ntree front set back\n4.7 metres\nT3 Cupressus sempervirens”\nSwans Golden Conifer”\nSouthern Neighbour’s\ntree front set back\n2.5 metres\nT4 Lophostemon confertus Council Verge 2.6 metres\nA project arborist (min. Qualification AQF5) is to be engaged throughout the\ndemolition and construction process\nA Project Arborist must be present on -site during the stages of construction\nwhen works are being undertaken that could impact on the tree canopy or root\nzone within the Tree Protection Zone to implement the tree protection measures\nas required.\nNo services shall be installed within the Tree Protection Zone of the tree unless\napproved by Council. Tree protection fencing shall be kept in place during\ndemolition, construction and also have a sign displaying ‘Tree Protection Zone’\nattached to the fence and must also include the name and contact details of the\nProject Arborist.\nWhere the Tree Protection Zone of trees on site or adjoining sites become\ncompromised by any excavation works, the Project Arborist shall be consulted to\nestablish the position of any major roots and determine the necessary measures\nto protect these roots. The recommendations of the Project Arborist shall be\nsubmitted to Council prior to any further demolition or construction works taking\nplace","stage":"before_cc","stage_basis":"heading","page":12},{"label":"28","code":null,"number":"28","title":"Pump-Out System Design for Stormwater Disposal","text":"The design of the pump-out system for stormwater disposal will be permitted for\ndrainage of basement areas only, and must be designed in accordance with the\nfollowing criteria:\n(a) The pump system must consist of two pumps, connected in parallel, with\neach pump being capable of emptying the holding tank at the rate equal\nto the rate of inflow for the one- hour duration storm. The holding tank\nmust be capable of holding four hour’s run off from a one-hour duration\nstorm of the 1 in 100 year storm;\n(b) The pump system must be regularly maintained and serviced, every six\n(6) months; and\n(c) Any drainage disposal to the street gutter from a pump system must have\na stilling sump provided at the property line, connected to the street\ngutter by a suitable gravity line.\nDetails and certification of compliance from a suitably qualified professional\nengineer specialising in hydraulic engineering must be provided to the Principal\nCertifier for approval with the Construction Certificate application.","stage":"before_cc","stage_basis":"heading","page":13},{"label":"29","code":null,"number":"29","title":"Geotechnical Report","text":"The applicant must submit a Geotechnical Report, prepared by a suitably qualified\nprofessional engineer specialising in geotechnical engineering. The Geotechnical\nReport must address dilapidation reports, all site works and construction. This is\nto be su bmitted to the Principal Certifier and Council (where Council is not the\nCertifier) before the issue of the Construction Certificate and must include:\n(a) Investigations certifying the stability of the site and specifying the design\nconstraints to be placed on the foundation, any earthworks, stabilization\nworks and any excavations.\n(b) Dilapidation Reports on the adjoining properties including, but not limited to","stage":"before_cc","stage_basis":"heading","page":14},{"label":"30","code":null,"number":"30","title":"","text":"Boden Avenue and 34 Boden Avenue prior to any excavation of site works.\nThe Dilapidation Report must include assessments on, but not limited to, the\ndwellings at those addresses and any external paths, grounds etc. This must\nbe submitted to the Principal Certifier and the adjoining residents as part of\nthe application for the Construction Certificate. Adjoining residents must be\nprovided with the report five (5) working days prior to any works on the site.\n(c) On-site guidance by a vibration specialist during the early part of excavation.\n(d) Measures to minimise vibration damage and loss of support to other\nbuildings. Where possible any excavation into rock is to be carried out with\ntools such as rock saws which reduce vibration to adjoining buildings and\nassociated structures. Where a hydraul ic hammer is to be used within 30\nmetres of any building (other than a path or a fence) the report must detail\nthe maximum size of hammer to be used and provide all reasonable\nrecommendations to manage impacts.\n(e) Sides of the excavation must be piered prior to any excavation occurring to\nreinforce the walls of the excavation to prevent any subsidence to the\nrequired setbacks and neighbouring sites.\n30 Compliance with Swimming Pool Act 1992\nThe alterations and additions to the dwelling house subject of this consent must\nnot generate any non-compliance with the Swimming Pools Act 1992, Swimming\nPool Regulation 2018, and the Building Code of Australia. Details of compliance\nmust be the illustra\nted on the plans lodged with the application for the\nConstruction Certificate","stage":"before_cc","stage_basis":"heading","page":14},{"label":"31","code":null,"number":"31","title":"Swimming Pools - Use and Maintenance","text":"The following apply to the construction, use and maintenance of swimming pools\nand spas:\n(a) No ground level may be raised or filled except where shown specifically on\nthe approved plans;\n(b) All pool or spa waste water is to be discharged to the sewer according to the\nrequirements of Sydney Water;\n(c) The swimming pool must not be used for commercial or professional\npurposes;\n(d) Paved areas must be designed to ensure drainage flows to the landscaped\nareas or a suitable lawful drainage system; and\n(e) Any lighting external to the pool or spa must be arranged to minimise glaring\nnuisance to adjoining owners.","stage":"before_cc","stage_basis":"heading","page":14},{"label":"32","code":null,"number":"32","title":"Demolition & Asbestos","text":"The demolition work must comply with the provisions of Australian Standard\nAS2601:2001 - Demolition of Structures, NSW Work Health & Safety Act 2011 and\nthe NSW Work Health & Safety Regulation 2011 . The work plans required by\nAS2601:2001 must be accompanied by a written statement by a suitably qualified\nperson that the proposals contained in the work plan comply with the safety\nrequirements of the Standard. The work plans and the safety statement must be\nsubmitted to the Principal Certifier prior to the commencement of works.\nFor demolition work which involves the removal of asbestos, the asbestos\nremoval work must be carried out by a licensed asbestos removalist who is\nlicensed to carry out the work in accordance with the NSW Work Health & Safety\nAct 2011 and the NSW Work Health & Safety Regulation 2011 unless specified in\nthe Act or Regulation that a license is not required.\nAll demolition work including the removal of asbestos, must be undertaken in\naccordance with the Demolition Code of Practice (NSW Work Cover July 2015)","stage":"before_work","stage_basis":"heading","page":15},{"label":"33","code":null,"number":"33","title":"Demolition Notification Requirements","text":"The following notification requirements apply to this consent:\n(a) The builder must notify adjoining residents five (5) working days prior to\ndemolition. Such notification will be a clearly written note giving the date\ndemolition will commence, contact details of the builder, licensed asbestos\ndemolisher and the appropri ate regulatory authority. Notification must be\nplaced in the letterbox of every premises (including every residential flat or\nunit, if any) either side and immediately at the rear of the demolition site.\n(b) Five (5) working days prior to demolition, the builder must provide written\nnotification to Council advising of the demolition date, details of the SafeWork\nlicensed asbestos demolisher and the list of residents advised of the\ndemolition.\n(c) On demolition sites where buildings to be demolished contain asbestos, a\nstandard commercially manufactured sign containing the words “DANGER\nASBESTOS REMOVAL IN PROGRESS” measuring not less than 400mm x\n300mm must be erected in a prominent visible position (from street frontage)\non the site. The sign must be erected prior to demolition work commencing\nand will remain in place until such time as all asbestos material has been\nremoved from the site to an approved waste facility.","stage":"before_work","stage_basis":"heading","page":15},{"label":"34","code":null,"number":"34","title":"Demolition Work Involving Asbestos Removal","text":"Work involving bonded asbestos removal work (of an area of more than 10 square\nmetres) or friable asbestos removal work must be undertaken by a person who\ncarries on a business of such removal work in accordance with a licence under\nclause 458 of the\nWork Health and Safety Regulation 2011","stage":"before_work","stage_basis":"heading","page":16},{"label":"35","code":null,"number":"35","title":"Utility Arrangements","text":"Arrangements must be made with utility authorities in respect to the services\napplied those authorities to the development. The cost associated with the\nprovision or adjustment of services within the road and footway areas will be at\nthe applicant’s expense.","stage":"before_work","stage_basis":"heading","page":16},{"label":"36","code":null,"number":"36","title":"Erosion and sediment controls in place","text":"Before any site work commences, the Certifier must be satisfied the erosion and\nsediment controls in the erosion and sediment control plan which was provided\nto the Certifier are in place. These controls must remain in place until any bare\nearth has been restabilised in accordance with the\nerosion and sediment control plan.","stage":"before_work","stage_basis":"heading","page":16},{"label":"37","code":null,"number":"37","title":"Tree protection measures","text":"Before any site work commences, the principal certifier, or council where a\nprincipal certifier is not required, must be satisfied the measures for tree\nprotection detailed in the construction site management plan are in place.","stage":"before_work","stage_basis":"heading","page":16},{"label":"38","code":null,"number":"38","title":"Dilapidation report","text":"Before any site work commences, a dilapidation report must be prepared by a\nsuitably qualified engineer detailing the structural condition of adjoining\nbuildings, structures or works and public land, to the satisfaction of the Certifier.\nWhere access has not been granted to any adjoining properties to prepare the\ndilapidation report, the report must be based on a survey of what can be\nobserved externally and demonstrate, in writing, to the satisfaction of the\nCertifier, that all reasonable steps were taken to obtain access to the adjoining\nproperties.\nNo less than seven (7) days before any site work commences, adjoining building\nowner(s) must be provided with a copy of the dilapidation report for their\nproperty(ies) and a copy of the report(s) must be provided to council (where\ncouncil is not the principal certifier) at the same time.","stage":"before_work","stage_basis":"heading","page":16},{"label":"39","code":null,"number":"39","title":"Dust Control","text":"Where a dust nuisance is likely to occur, suitable screens and barricades must be\nerected during the demolition, excavation and building works. Water sprays must\nbe used on the site to reduce the emission of dust. Screening must consist of a\nminimum 2 metr es height of shade cloth or similar material secured to a chain\nwire fence or the like and must be modified as required should it fail to adequately\ncontrol any dust nuisance.","stage":"before_work","stage_basis":"heading","page":17},{"label":"40","code":null,"number":"40","title":"Hours of work","text":"Site work must only be carried out between the following times -\nFor building construction and delivery of machinery and materials from 7:00am\nto 5:00pm on Monday to Saturday (excluding Public Holidays)\nFor demolition, excavation and/or construction works that involve heavy\nmachinery, noisy trades, or the like from 7:00am to 5:00pm on Monday to Friday\n(excluding Public Holidays)\nSite work is not to be carried out outside of these times except where there is an\nemergency, or for urgent work directed by a police officer or a public authority.","stage":"during_work","stage_basis":"heading","page":17},{"label":"41","code":null,"number":"41","title":"Ground Levels and Retaining Walls","text":"The ground levels of the site must not be excavated, raised or filled and retaining\nwalls constructed on the allotment boundary, except where indicated on\napproved plans or approved by Council.","stage":"during_work","stage_basis":"heading","page":17},{"label":"42","code":null,"number":"42","title":"Physical Connection of Stormwater to Site","text":"Work must not proceed above the ground floor slab level of the building until\nthere is physical connection of the approved stormwater drainage system from\nthe land the subject of this consent to street kerb and gutter in Boden Avenue.","stage":"during_work","stage_basis":"heading","page":17},{"label":"43","code":null,"number":"43","title":"Cost of Work to be Borne by the Applicant","text":"The applicant must pay the cost of all works associated with the construction of\nthe development that occurs on Council property. Care must be taken to protect\nCouncil’s roads, including the made footway, kerbs, etc, and where plant and\nvehicles enter the site, the footway must be protected against damage by deep -\nsectioned timber members laid crosswise, held together by hoop iron straps and\nchamfered at their ends. This construction must be maintained in a state of good\nrepair and condition throughout the course of construction.","stage":"during_work","stage_basis":"heading","page":18},{"label":"44","code":null,"number":"44","title":"Responsibility for changes to public infrastructure","text":"While site work is being carried out, any costs incurred as a result of the approved\nremoval, relocation or reconstruction of infrastructure (including ramps,\nfootpaths, kerb and gutter, light poles, kerb inlet pits, service provider pits, street\ntrees or any other infrastructure in the street footpath area) must be paid as\ndirected by the consent authority.","stage":"during_work","stage_basis":"heading","page":18},{"label":"45","code":null,"number":"45","title":"Obstruction of Road or Footpath","text":"The use of the road or footpath for the storage of any building materials, waste\nmaterials, temporary toilets, waste or skip bins, or any other matter is not\npermitted unless separately approved by Council under Section 138 of the Roads\nAct 1993 and under Section 68 of the Local Government Act 1993 . Penalty\ninfringement Notices may be issued for any offences and severe penalties apply.","stage":"during_work","stage_basis":"heading","page":18},{"label":"46","code":null,"number":"46","title":"Construction Management Plan","text":"The builder must ensure that the approved Construction Traffic Management Plan\nis to be strictly complied with and kept on site at all times during construction\nworks.","stage":"during_work","stage_basis":"heading","page":18},{"label":"47","code":null,"number":"47","title":"Procedure for critical stage inspections","text":"While building work is being carried out, the work must not continue after each\ncritical stage inspection unless the principal certifier is satisfied the work may\nproceed in accordance with this consent and the relevant construction certificate.","stage":"during_work","stage_basis":"heading","page":18},{"label":"48","code":null,"number":"48","title":"Registered Surveyors Report","text":"A report must be submitted to the Principal Certifier at each of the following\napplicable stages of construction:\n(a) Set out before commencing excavation.\n(b) Floor slabs or foundation wall, before formwork or commencing\nbrickwork.\n(c) Completion of Foundation Walls - Before any construction of flooring,\ndetailing the location of the structure relative to adjacent boundaries\nand floor levels relative to the datum shown on the approved plans.\n(d) Completion of Floor Slab Formwork - Before pouring of concrete/walls\nconstruction, detailing the location of the structure relative to adjacent\nboundaries and floor levels relative to the datum shown on the approved\nplans. In multi -storey buildings a furt her survey must be provided at\neach subsequent storey.\n(e) Completion of any Pool Formwork - Before concreting of pool shell,\ndetailing the location of the pool relative to the adjacent boundaries and\nits height relative to the datum shown on the approved plans.\n(f) Completion of any Roof Framing - Before roof covered detailing\neaves/gutter setback from boundaries.\n(g) Completion of all Work - Detailing the location of the structure (including\neaves/gutters) relative to adjacent boundaries and its height relative to\nthe datum shown on the approved plans. A final Check Survey must\nindicate the reduced level of the main ridge.\nWork must not proceed beyond each stage until the Principal Certifier is satisfied\nthat the height and location of the building is proceeding in accordance with the\napproved plans.","stage":"during_work","stage_basis":"heading","page":18},{"label":"49","code":null,"number":"49","title":"Implementation of the site management plans while site work is being carried","text":"out:\na) the measures required by the construction site management plan and the\nerosion and sediment control plan (plans) must be implemented at all\ntimes, and\nb) a copy of these plans must be kept on site at all times and made available\nto council officers upon request.","stage":"during_work","stage_basis":"heading","page":19},{"label":"50","code":null,"number":"50","title":"Tree Removal on Private Land","text":"The trees identified as ‘to be removed/pruned’ on the approved plans or by\nconditions of this consent must be removed in accordance with AS4373 -2007 and\nthe Amenity Tree Industry Code of Practice (SafeWork NSW, August 1998).","stage":"during_work","stage_basis":"heading","page":19},{"label":"51","code":null,"number":"51","title":"Tree protection during work","text":"While site work is being carried out, all required tree protection measures must\nbe maintained in good condition in accordance with:\na) the construction site management plan under this consent,\nb) the relevant requirements of AS 4970 Protection of trees on development\nsites,\nc) Council’s relevant development control plan (in force as at the date of\ndetermination of this consent) and\nd) any arborist’s report approved under this consent.\nThis includes maintaining adequate soil grades and ensuring all machinery,\nbuilders refuse, spoil and materials remain outside tree protection zones.","stage":"during_work","stage_basis":"heading","page":20},{"label":"52","code":null,"number":"52","title":"Waste management","text":"While site work is being carried out:\na) all waste management must be undertaken in accordance with the waste\nmanagement plan, and\nb) upon disposal of waste, records of the disposal must be compiled and\nprovided to the Certifier, or Council where a certifier is not required,\ndetailing the following:\ni) The contact details of the person(s) who removed the waste\nii) The waste carrier vehicle registration\niii) The date and time of waste collection\niv) A description of the waste (type of waste and estimated quantity)\nand whether the waste is to be reused, recycled or go to landfill\nv) The address of the disposal location(s) where the waste was taken\nvi) The corresponding tip docket/receipt from the site(s) to which the\nwaste is transferred, noting date and time of delivery, description\n(type and quantity) of waste.\nIf waste has been removed from the site under an EPA Resource Recovery Order\nor Exemption, records in relation to that Order or Exemption must be\nmaintained and provided to the principal certifier and council.","stage":"during_work","stage_basis":"heading","page":20},{"label":"53","code":null,"number":"53","title":"Connection to the Network","text":"Where works within the road reserve are to be carried out by the developer, a\nRoad Opening Permit must be obtained from Council before the\ncommencement of any work.","stage":"during_work","stage_basis":"heading","page":20},{"label":"54","code":null,"number":"54","title":"Noise and Vibration requirements","text":"While site work is being carried out, noise generated from the site must not\nexceed an LAeq (15 min) of <5dB/ INSERT LESS THAN 5dB>(A) above background\nnoise, when measured at a lot boundary of the site.","stage":"during_work","stage_basis":"heading","page":21},{"label":"55","code":null,"number":"55","title":"Soil management","text":"While site work is being carried out, the Certifier must be satisfied all soil\nremoved from or imported to the site is managed in accordance with the\nfollowing requirements:\na) All excavated material removed from the site must be classified in\naccordance with the EPA’s Waste Classification Guidelines before it is\ndisposed of at an approved waste management facility and the\nclassification and the volume of material removed must be reported to the\nCertifier.\nb) All fill material imported to the site must be:\ni) Virgin Excavated Natural Material as defined in Schedule 1 of the\nProtection of the Environment Operations Act 1997, or\nii) a material identified as being subject to a resource recovery exemption\nby the NSW EPA, or\niii) a combination of Virgin Excavated Natural Material as defined in\nSchedule 1 of the Protection of the Environment Operations Act 1997\nand a material identified as being subject to a resource recovery\nexemption by the NSW EPA.","stage":"during_work","stage_basis":"heading","page":21},{"label":"56","code":null,"number":"56","title":"Swimming Pools - Filling with Water","text":"The pool must not be filled until the safety fences have been completed in\naccordance with the approved plans and specifications and inspected by the\nPrincipal Certifier","stage":"during_work","stage_basis":"heading","page":21},{"label":"57","code":null,"number":"57","title":"BASIX Certificate","text":"All energy efficiency measures as detailed in the approved BASIX Certificate in the\nplans approved with the Development Consent, must be implemented before the\nissue of any Occupation Certificate.","stage":"before_oc","stage_basis":"heading","page":21},{"label":"58","code":null,"number":"58","title":"BASIX Compliance Certificate","text":"A Compliance Certificate must be provided to the Principal Certifier regarding the\nimplementation of all energy efficiency measures as detailed in the approved\nBASIX Certificate before any Occupation Certificate is issued.","stage":"before_oc","stage_basis":"heading","page":22},{"label":"59","code":null,"number":"59","title":"Completion of Landscape Works and Tree Works","text":"The approved landscape works have identified that the side setback area between\nthe dwelling and boundary be nominated as landscaped area to ensure\ncompliance with the minimum landscape area requirements. In this regard, this\narea must be maintained as landscaped area and must only be used for growing\nplants, grasses and trees and must not include any building, structure or hard\npaving (including rainwater tanks, air- conditioning units of ground mounted hot\nwater systems).","stage":"before_oc","stage_basis":"heading","page":22},{"label":"60","code":null,"number":"60","title":"Minor Development","text":"Internal driveways and parking spaces must be adequately paved with concrete\nor bitumen, or interlocking pavers to provide a dust-free surface.","stage":"before_oc","stage_basis":"heading","page":22},{"label":"61","code":null,"number":"61","title":"Stormwater Certification of the Constructed Drainage Works (Minor)","text":"The constructed stormwater system must be certified by a suitably qualified\nperson, in accordance with Council’s Stormwater Management Code, prior to the\nissue of any Occupation Certificate.","stage":"before_oc","stage_basis":"heading","page":22},{"label":"62","code":null,"number":"62","title":"Vehicular Crossing - Minor Development","text":"The vehicular crossing and footpath works must be constructed by a private\ncontractor at the expense of the applicant, in accordance with the Works Permit\nApproval issued by Council’s Engineering Design Services and in accordance with\nCouncil’s Driveway Specifications.\nAny existing vehicular crossing and laybacks which are redundant must be\nremoved. The kerb and gutter, any other footpath and turf areas must be restored\nat the expense of the applicant and in accordance with Council’s Driveway\nSpecifications.\nThe work must be completed before the issue of any Occupation Certificate.","stage":"before_oc","stage_basis":"heading","page":22},{"label":"63","code":null,"number":"63","title":"Release of securities","text":"When Council receives an occupation certificate an application may be lodged to\nrelease the securities held in accordance with Council’s Policy.","stage":"before_oc","stage_basis":"heading","page":23},{"label":"64","code":null,"number":"64","title":"Repair of infrastructure","text":"","stage":"before_oc","stage_basis":"heading","page":23},{"label":"65","code":null,"number":"65","title":"Works-as-executed plans and any other documentary evidence","text":"Before the issue of the relevant occupation certificate, works-as-executed plans,\nany compliance certificates and any other evidence confirming the following\ncompleted works must be submitted to the satisfaction of the principal certifier:\na) All stormwater drainage systems and storage systems, and\nb) The following matters that council requires to be documented\n• Positive Covenant and restriction-on-use\nc) A copy of the plans must be provided to council with the Occupation\nCertificate.","stage":"before_oc","stage_basis":"heading","page":23},{"label":"66","code":null,"number":"66","title":"Removal of waste upon completion","text":"","stage":"before_oc","stage_basis":"heading","page":23},{"label":"67","code":null,"number":"67","title":"Electricity Supply","text":"Prior to the issue of any Occupation Certificate, evidence must be provided\ndemonstrating that the development has been connected to the Ausgrid network.","stage":"before_oc","stage_basis":"heading","page":24},{"label":"68","code":null,"number":"68","title":"Completion of public utility services","text":"Before the issue of the relevant occupation certificate, confirmation must be\nobtained from the relevant authority that any adjustment or augmentation of any\npublic utility services including gas, water, sewer, electricity, street lighting and\ntelecommunic\nations, required as a result of the development, have been\ncompleted and this confirmation must be provided to the principal certifier.","stage":"before_oc","stage_basis":"heading","page":24},{"label":"69","code":null,"number":"69","title":"Restriction to User and Positive Covenant for Stormwater Management System","text":"Prior to the issue of any Occupation Certificate, the applicant must register a\nPositive Covenant and a Restriction as to User under section 88E and or section\n88B of the Conveyancing Act as appropriate in favour of Council, ensuring the\nongoing retention, maintenance and operation of the stormwater facility (on-site\ndetention, pump-out, charged lines, water sensitive urban design, surface flow\npath, finished pavement and ground levels etc.).\nWhere any drainage line or service conduit is to traverse any property other than\nthat which it serves, an appropriate easement will be required. In this case, the\napplicant must register an easement no less than 1200mm wide over the\nproposed drainage line or service concurrently with any subdivision registration.\nThe wording on the 88E and or 88B Instrument is to make reference to the Council\nfile where the Construction plans and the Work As Executed (as built), plans are\nheld. Typical wording can be obtained from Council's Specification for the\nManagement of Stormwater document.","stage":"before_oc","stage_basis":"heading","page":24},{"label":"70","code":null,"number":"70","title":"Maintenance Schedule - On-site Stormwater Management","text":"A Maintenance Schedule for the proposed on -site stormwater management\nmeasures must be prepared by a suitably qualified professional hydraulic\nengineer and submitted to Council. The Maintenance Schedule must outline the\nrequired maintenance works, how and when these will be done and who will be\ncarrying out these maintenance works.","stage":"before_oc","stage_basis":"heading","page":24},{"label":"71","code":null,"number":"71","title":"Post-construction dilapidation report","text":"Before the issue of an occupation certificate a post- construction dilapidation\nreport must be prepared by a suitably qualified engineer, to the satisfaction of\nthe Certifier, detailing whether:\na) after comparing the pre-construction dilapidation report to the post-\nconstruction dilapidation report required under this condition, there has\nbeen any structural damage to any adjoining buildings; and\nb) where there has been structural damage to any adjoining buildings, that it\nis a result of the work approved under this development consent, and\na copy of the post-construction dilapidation report must be provided to council\n(where council is not the principal certifier or a principal certifier is not required)\nand to the relevant adjoining property owner(s).","stage":"before_oc","stage_basis":"heading","page":25},{"label":"72","code":null,"number":"72","title":"Maintenance of Landscaping","text":"All trees and plants forming part of the landscaping must be maintained.\nMaintenance includes watering, weeding, removal of rubbish from tree bases,\nfertilising, pest and disease control, replacement of dead or dying plants and any\nother operations required to maintain healthy trees, plants and turfed areas.","stage":"ongoing","stage_basis":"heading","page":25},{"label":"73","code":null,"number":"73","title":"Greywater System","text":"In order to conserve and re -use water, Council encourages all development for\nnew dwellings to incorporate a greywater reuse system. The system can\nincorporate a greywater diversion device or a domestic greywater treatment\nsystem. Any system installed must ensure that it complies with the Plumbing Code\nof Australia. Th system must be maintained at all times and must not result in any\nadverse amenity impacts on the subject premises and surrounding properties.","stage":"ongoing","stage_basis":"heading","page":25},{"label":"74","code":null,"number":"74","title":"Maintenance of wastewater and stormwater treatment device","text":"During occupation and ongoing use of the building, all wastewater and\nstormwater treatment devices (including drainage systems, sumps and traps, and\non-site detention) must be regularly maintained to remain effective and in\naccordance with any positive covenant (if applicable).","stage":"ongoing","stage_basis":"heading","page":25},{"label":"75","code":null,"number":"75","title":"Entering and Exiting of Vehicles","text":"All vehicles must enter and exit the premises in a forward direction.","stage":"ongoing","stage_basis":"heading","page":25},{"label":"76","code":null,"number":"76","title":"Swimming Pools - Resuscitation Notice","text":"An expired air resuscitation warning notice complying with the Swimming Pools\nAct 1992 must be affixed in a prominent position adjacent to the pool.","stage":"ongoing","stage_basis":"heading","page":26},{"label":"77","code":null,"number":"77","title":"Private Swimming Pools & Spas - Pump Noise","text":"The swimming pool or spa pump and associated equipment must be located so\nthat the noise emitted does not exceed 5db(A) above the background level. If this\ncannot be achieved a ventilated and sound -proofed enclosure the pump to\nachieve the required noise levels.\nSwimming pool is to be installed with a timer that limits the recirculation and\nfiltration systems operation such that it does not emit noise that can be heard\nwithin a habitable room in any other residential premises (regardless of whether\nany door or window to that room is open):\n(a) before 8 am or after 8 pm on any Sunday or public holiday, or\n(b) before 7 am or after 8pm on any other day.","stage":"ongoing","stage_basis":"heading","page":26}]});
